def get_winning_F_alt2(max_F, max_turns):
    winning_Fs = []
    for F in range(2, max_F + 1):
        W = set()
        for k in range(1, max_turns + 1):
            new_W = set(W)
            y_set = set()
            # Find y such that y=F or {y-1, y+1} \subseteq W
            # But y must be a divisor or multiple of x AND y != x.
            # This means x must be a proper divisor or proper multiple of y.

            # This is easier to think about as:
            # y is a "good" submit if (y == F) or ({y-1, y+1} \subseteq W).
            # x is in new_W if there is a good y such that y is a proper divisor or proper multiple of x.

            # To find all such x, we need all good y's.
            good_y = set()
            if True: # y = F is always a candidate
                good_y.add(F)
            for w in W:
                if w + 2 in W:
                    good_y.add(w + 1)

            for y in good_y:
                if y == 1: continue
                # x is a proper divisor of y
                for d in range(1, int(y**0.5) + 1):
                    if y % d == 0:
                        if d != y: new_W.add(d)
                        if y // d != y: new_W.add(y // d)
                # x is a proper multiple of y
                if y <= 1000:
